"https://cwe.mitre.org/data/definitions/338.html"]}},{"ruleId":"JS021","contentHash":"6f4878af7fa7f0487df5fbaaadad3b6c4c565fc3a1908a73480c8abbcb0bbfd6","definition":{"id":"JS021","languages":["javascript","typescript"],"title":"Запуск процесса через shell","description":"spawn или execFile явно включает оболочку; недоверенные аргументы могут стать командами.","severity":"high","cwe":"CWE-78","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:spawn|spawnSync|execFile|execFileSync)\\s*\\([^;{}]{0,600}\\{[^{}]{0,400}\\bshell\\s*:\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"injection","recommendation":"Используйте shell: false, фиксированный executable и массив проверенных аргументов.","references":["https://cwe.mitre.org/data/definitions/78.html"]}},{"ruleId":"PY021","contentHash":"febcb590a949339efb9b1ce3536f41bdc7fc546f862c3903390057845611ccc4","definition":{"id":"PY021","languages":["python"],"title":"Небезопасный SSL-контекст","description":"SSL-контекст создаётся без проверки сертификата либо проверка явно отключена.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"high","pattern":"\\bssl\\._create_unverified_context\\s*\\(|\\bverify_mode\\s*=\\s*ssl\\.CERT_NONE\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"transport","recommendation":"Используйте ssl.create_default_context(), CERT_REQUIRED и проверку имени сервера.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"PY022","contentHash":"9b83b01d00a4083df9954a94ae5cb5be19d438c8e7e79bd15d4801ddcac344e2","definition":{"id":"PY022","languages":["python"],"title":"Отключено экранирование Jinja","description":"Jinja Environment явно отключает автоматическое экранирование; при выводе недоверенных данных в HTML возможен XSS.","severity":"high","cwe":"CWE-79","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:jinja2\\.)?Environment\\s*\\((?:[^();]|\\([^()]*\\)){0,400}?\\bautoescape\\s*=\\s*False\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"xss","recommendation":"Для HTML-шаблонов включите autoescape или select_autoescape([''html'', ''htm'', ''xml'']).","references":["https://cwe.mitre.org/data/definitions/79.html"]}},{"ruleId":"JAVA021","contentHash":"a3402b691b7669122ca2a5731a43b463984472b19f1ab7ddaf4979402b396301","definition":{"id":"JAVA021","languages":["java","kotlin"],"title":"Небезопасная десериализация XMLDecoder","description":"XMLDecoder создаёт объекты и вызывает методы из XML; недоверенный документ может выполнить код.","severity":"critical","cwe":"CWE-502","owasp":"A08:2021","confidence":"high","pattern":"\\b(?:new\\s+(?:java\\.beans\\.)?XMLDecoder|java\\.beans\\.XMLDecoder|XMLDecoder)\\s*\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"deserialization","recommendation":"Не передавайте недоверенные документы в XMLDecoder; используйте формат данных со строгой схемой без создания произвольных объектов.","references":["https://cwe.mitre.org/data/definitions/502.html"]}},{"ruleId":"CS004","contentHash":"6e29fb26514f7a852fe5b3f8706da08471b291b0930544e7aa12ad968cf74a71","definition":{"id":"CS004","languages":["csharp"],"title":"Разрешены типы из JSON","description":"Newtonsoft.Json TypeNameHandling разрешает создавать типы, указанные в JSON; без строгого binder это опасно для недоверенного ввода.","severity":"high","cwe":"CWE-502","owasp":"A08:2021","confidence":"medium","pattern":"\\bTypeNameHandling\\s*=\\s*(?:Newtonsoft\\.Json\\.)?TypeNameHandling\\.(?:All|Auto|Objects|Arrays)\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"deserialization","recommendation":"Установите TypeNameHandling.None; при необходимой полиморфности применяйте строгий allowlist в ISerializationBinder.","references":["https://cwe.mitre.org/data/definitions/502.html"]}},{"ruleId":"CS005","contentHash":"118902eea31b517c11149488d456a84a31ca5b7a1b33ab9220e5113f1439228d","definition":{"id":"CS005","languages":["csharp"],"title":"Разрешена обработка DTD","description":"XML-парсер разрешает DTD; внешние сущности и расширение сущностей требуют дополнительных ограничений.","severity":"medium","cwe":"CWE-611","owasp":"A05:2021","confidence":"medium","pattern":"\\bDtdProcessing\\s*=\\s*(?:System\\.Xml\\.)?DtdProcessing\\.Parse\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"xxe","recommendation":"Установите DtdProcessing.Prohibit и XmlResolver = null; ограничьте размер документа и расширение сущностей.","references":["https://cwe.mitre.org/data/definitions/611.html"]}},{"ruleId":"PHP008","contentHash":"dc69156b6e7330ef251b7b89b2827bddda1918c76790dd961acb4a4039065423","definition":{"id":"PHP008","languages":["php"],"title":"Отключена проверка TLS в cURL","description":"cURL явно отключает проверку сертификата или имени TLS-сервера.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"high","pattern":"\\bCURLOPT_SSL_VERIFY(?:PEER|HOST)\\s*(?:,|=>)\\s*(?:false|0)\\b","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"file","category":"transport","recommendation":"Включите CURLOPT_SSL_VERIFYPEER и установите CURLOPT_SSL_VERIFYHOST = 2; настройте доверенный CA.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"CFG009","contentHash":"506c89f3136db5088d4ded7129c16e8a8c8091225172228d81a1919055ba43c5","definition":{"id":"CFG009","languages":["config"],"title":"Docker socket доступен контейнеру","description":"Конфигурация монтирует сокет Docker daemon; доступ к нему может дать управление контейнерами и узлом даже при read-only mount.","severity":"high","cwe":"CWE-250","owasp":"A05:2021","confidence":"high","pattern":"^\\s*(?:-\\s*[\"'']?\\/(?:var\\/)?run\\/docker\\.sock\\s*:|(?:source|path)\\s*:\\s*[\"'']?\\/(?:var\\/)?run\\/docker\\.sock[\"'']?\\s*(?:#.*)?$)","patternFlags":"m","exclude":null,"excludeFlags":null,"scope":"file","category":"configuration","recommendation":"Уберите Docker socket из контейнера или используйте отдельный proxy с минимальным набором разрешённых API.","references":["https://cwe.mitre.org/data/definitions/250.html"]}},{"ruleId":"CFG010","contentHash":"00971e9fd460d92eecbc7288ab186507a9127cfb76f37d0fe1c92fc31958488e","definition":{"id":"CFG010","languages":["config"],"title":"Опасные capabilities контейнера","description":"Контейнер получает SYS_ADMIN или полный набор capabilities, что значительно расширяет его привилегии.","severity":"high","cwe":"CWE-250","owasp":"A05:2021","confidence":"high","pattern":"\\b(?:cap_add|add)\\s*:\\s*(?:\\[[^\\]\\n]*\\b(?:SYS_ADMIN|ALL)\\b[^\\]\\n]*\\]|(?:\\r?\\n\\s*-\\s*[\"'']?[A-Z_]+[\"'']?\\s*)*\\r?\\n\\s*-\\s*[\"'']?(?:SYS_ADMIN|ALL)[\"'']?\\b)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"file","category":"configuration","recommendation":"Удалите SYS_ADMIN и ALL; сбросьте capabilities и добавьте только необходимые для конкретной операции.","references":["https://cwe.mitre.org/data/definitions/250.html"]}},{"ruleId":"CFG011","contentHash":"334470f89b7a712565c3f09b0558377cf294e1f93a0ee87e650ed1f7962e21aa","definition":{"id":"CFG011","languages":["config"],"title":"Отключён seccomp контейнера","description":"Контейнер явно запускается без фильтра системных вызовов seccomp.","severity":"high","cwe":"CWE-693","owasp":"A05:2021","confidence":"high","pattern":"\\bseccomp\\s*[:=]\\s*unconfined\\b|\\bseccompProfile\\s*:\\s*(?:\\{\\s*type\\s*:\\s*[\"'']?Unconfined[\"'']?\\s*\\}|\\s*\\n\\s*type\\s*:\\s*[\"'']?Unconfined[\"'']?\\b)","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"file","category":"configuration","recommendation":"Используйте seccompProfile.type: RuntimeDefault или ограниченный профиль Localhost; удалите seccomp=unconfined.","references":["https://cwe.mitre.org/data/definitions/693.html"]}},{"ruleId":"SEC010","contentHash":"a07c65e346e515176cecd7cdf911acc0cda9cd03ea32028356e7cfa903f8efa0","definition":{"id":"SEC010","languages":["javascript","typescript","python","java","php","go","csharp","ruby","kotlin","rust","swift","scala","shell","config","unknown"],"title":"Секретный ключ Stripe","description":"Найден ключ Stripe для production API.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"high","pattern":"\\b(?:sk|rk)_live_[A-Za-z0-9]{24,}\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Отзовите ключ Stripe и загрузите новый из хранилища секретов.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"SEC011","contentHash":"0e21868c6372076cbd436c73bd43418f2529d0f2db53ade95706ecac108e9240","definition":{"id":"SEC011","languages":["javascript","typescript","python","java","php","go","csharp","ruby","kotlin","rust","swift","scala","shell","config","unknown"],"title":"API-ключ Google","description":"Найден ключ Google API; проверьте ограничения API, адресов и приложений.","severity":"high","cwe":"CWE-798","owasp":"A07:2021","confidence":"medium","pattern":"\\bAIza[A-Za-z0-9_-]{35}(?![A-Za-z0-9_-])","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Удалите ключ из исходников, ограничьте его назначение и перевыпустите при утечке.","references":["https://cwe.mitre.org/data/definitions/798.html"]}},{"ruleId":"SEC012","contentHash":"c6b276fa2683590eb1ac396924798eeffb5b67e5bedbe4f2b7b73bf90a79d0c0","definition":{"id":"SEC012","languages":["javascript","typescript","python","java","php","go","csharp","ruby","kotlin","rust","swift","scala","shell","config","unknown"],"title":"Токен GitLab","description":"Найден personal access token GitLab.","severity":"critical","cwe":"CWE-798","owasp":"A07:2021","confidence":"high","pattern":"\\bglpat-[A-Za-z0-9_-]{20,}(?![A-Za-z0-9_-])","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Отзовите токен GitLab и перенесите 