nces":["https://cwe.mitre.org/data/definitions/89.html"]}},{"ruleId":"PY034","contentHash":"7a47b47278d2e428394a35f3e7149deaed64707be8ac24c238f79a1914a0fc98","definition":{"id":"PY034","languages":["python"],"title":"Flask отдаёт файл по HTTP-параметру","description":"Имя отдаваемого файла напрямую зависит от запроса.","severity":"high","cwe":"CWE-22","owasp":"A01:2021","confidence":"medium","pattern":"\\b(?:send_file|send_from_directory)\\s*\\([^\\n)]*\\brequest\\.(?:args|form|values|json)\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"validation","recommendation":"Выбирайте файл из фиксированного каталога по разрешённому идентификатору; проверяйте нормализованный путь.","references":["https://cwe.mitre.org/data/definitions/22.html"]}},{"ruleId":"PY035","contentHash":"1db7d06bc2f6e029277624396d400803ec80faeb9aa126392b5623369e8db2d5","definition":{"id":"PY035","languages":["python"],"title":"Ослаблены сессионные cookie Python","description":"Настройки сессионных cookie явно отключают Secure или HttpOnly.","severity":"medium","cwe":"CWE-614","owasp":"A07:2021","confidence":"medium","pattern":"\\bSESSION_COOKIE_(?:SECURE|HTTPONLY)[\"'']?\\s*(?:=|:)\\s*False\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"authentication","recommendation":"Включите SESSION_COOKIE_SECURE и SESSION_COOKIE_HTTPONLY для production-сессий.","references":["https://cwe.mitre.org/data/definitions/614.html"]}},{"ruleId":"PY036","contentHash":"42549a152aa13a8ea36395a0e308c675b90e1f14f6ce9928797e6f421b935c98","definition":{"id":"PY036","languages":["python"],"title":"PyTorch загружает произвольные объекты","description":"torch.load явно отключает weights_only и допускает десериализацию Python-объектов.","severity":"high","cwe":"CWE-502","owasp":"A08:2021","confidence":"medium","pattern":"\\btorch\\.load\\s*\\([^\\n)]*\\bweights_only\\s*=\\s*False\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","categor