html"]}},{"ruleId":"GO030","contentHash":"6c1d33b5c8e66a71eaa6ec8fc116ad472a3ca767daf877fcdb2cc0f7184735d1","definition":{"id":"GO030","languages":["go"],"title":"Слабый минимальный TLS в Go","description":"MinVersion явно допускает TLS 1.0, TLS 1.1 или SSL 3.0.","severity":"high","cwe":"CWE-326","owasp":"A02:2021","confidence":"high","pattern":"\\bMinVersion\\s*:\\s*tls\\.Version(?:TLS10|TLS11|SSL30)\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Установите MinVersion: tls.VersionTLS12 или TLS13.","references":["https://cwe.mitre.org/data/definitions/326.html"]}},{"ruleId":"GO031","contentHash":"1d0d98226f23bb85b9a852b985e8733e07c79edc395133f6b13e699e8ff8d616","definition":{"id":"GO031","languages":["go"],"title":"Устаревший шифр Go","description":"Используется DES, TripleDES или RC4.","severity":"high","cwe":"CWE-327","owasp":"A02:2021","confidence":"high","pattern":"\\b(?:des\\.(?:NewCipher|NewTripleDESCipher)|rc4\\.NewCipher)\\s*\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"crypto","recommendation":"Используйте AES-GCM или ChaCha20-Poly1305.","references":["https://cwe.mitre.org/data/definitions/327.html"]}},{"ruleId":"GO032","contentHash":"71446f35afe7cf63d4215de2b093a9b9c0ea93b163fd4f918de7372db000ea81","definition":{"id":"GO032","languages":["go"],"title":"Слабый RSA-ключ Go","description":"rsa.GenerateKey создаёт ключ короче 2048 бит.","severity":"high","cwe":"CWE-326","owasp":"A02:2021","confidence":"high","pattern":"\\brsa\\.GenerateKey\\s*\\(\\s*[^,\\n]+,\\s*(?:512|768|1024)\\s*\\)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"crypto","recommendation":"Используйте ключ не менее 2048 бит и crypto/rand.Reader.","references":["https://cwe.mitre.org/data/definitions/326.html"]}},{"ruleId":"GO033","contentHash":"a811265940ba235adc64dff7bd8bba25350674d243dc16c473be7204a0fbeba2","definition":{"id":"GO033","languages":["go"],