nguages":["rust"],"title":"SQL-инъекция rusqlite","description":"query_row/prepare получает SQL из format!.","severity":"critical","cwe":"CWE-89","owasp":"A03:2021","confidence":"medium","pattern":"\\.(?:query_row|prepare)\\s*\\(\\s*&?format!\\s*\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Используйте статический SQL и параметры rusqlite params!.","references":["https://cwe.mitre.org/data/definitions/89.html"]}},{"ruleId":"RS033","contentHash":"04f48109610b79ffd9cb69b5b738c8eaa69e5ff3fcb53b4f6df194a2699c91c0","definition":{"id":"RS033","languages":["rust"],"title":"Rust создаёт общедоступный файл","description":"OpenOptionsExt явно задаёт режим 0777 или 0666.","severity":"high","cwe":"CWE-732","owasp":"A05:2021","confidence":"medium","pattern":"\\.mode\\s*\\(\\s*0o(?:777|666)\\s*\\)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Задайте минимальные права, например 0o600 для чувствительных файлов.","references":["https://cwe.mitre.org/data/definitions/732.html"]}},{"ruleId":"SWIFT030","contentHash":"0932fbf84abe297c07c4cdcee576fdcb2dff00e548ee39c08a66fe85715b0f1d","definition":{"id":"SWIFT030","languages":["swift"],"title":"Keychain доступен при блокировке","description":"Выбран устаревший уровень Keychain AccessibleAlways.","severity":"high","cwe":"CWE-922","owasp":"A05:2021","confidence":"medium","pattern":"\\bkSecAttrAccessibleAlways(?:ThisDeviceOnly)?\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Используйте kSecAttrAccessibleWhenUnlocked или более строгий уровень с учётом фонового доступа.","references":["https://cwe.mitre.org/data/definitions/922.html"]}},{"ruleId":"SWIFT031","contentHash":"c44f88b7094fe92c60c445e8ee958820c9b52503861a2cd61af805b53d6894aa","definition":{"id":"SWIFT031","languages":["swift"],"title":"ECB в CommonCrypto","description":"CommonCrypto использует режим ECB, который раскрывает структуру повторяющихся блоков.","severity":"high","cwe":"CWE-327","owasp":"A02:2021","confidence":"high","pattern":"\\bkCCOptionECBMode\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"crypto","recommendation":"Используйте AEAD, например AES-GCM, с уникальным nonce и проверкой authentication tag.","references":["https://cwe.mitre.org/data/definitions/327.html"]}},{"ruleId":"SWIFT032","contentHash":"10cab315a88bf1416d651af4f639c4c4373007ca9927f406b63a1d1d3f078cc2","definition":{"id":"SWIFT032","languages":["swift"],"title":"SQL-интерполяция Swift","description":"SQLite SQL содержит строковую интерполяцию Swift.","severity":"critical","cwe":"CWE-89","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:sqlite3_exec|sqlite3_prepare_v2)\\s*\\([^\\n]*\"[^\"\\n]*\\\\\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Используйте sqlite3_bind_* с placeholders и фиксированный SQL.","references":["https://cwe.mitre.org/data/definitions/89.html"]}},{"ruleId":"SWIFT033","contentHash":"6a8217044ccb85e4ed798e53341f3031eb58795aa80a89aa8bf59b6246a2f66b","definition":{"id":"SWIFT033","languages":["swift"],"title":"Небезопасное unarchive Swift","description":"Legacy NSKeyedUnarchiver загружает объекты без списка разрешённых классов.","severity":"high","cwe":"CWE-502","owasp":"A08:2021","confidence":"medium","pattern":"\\bNSKeyedUnarchiver\\.unarchive(?:Object|TopLevelObjectWithData)\\s*\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"deserialization","recommendation":"Используйте unarchivedObject(ofClass:from:) или ofClasses с NSSecureCoding.","references":["https://cwe.mitre.org/data/definitions/502.html"]}},{"ruleId":"SCALA030","contentHash":"558ac73f8eb8a66dd7c75cca88d341cca886faa894c7b7137518dcba115355af","definition":{"id":"SCALA030","languages":["scala"],"title":"Слабая генерация security-токена Scala","description":"Токен создаётся через scala.util.Random.","severity":"medium","cwe":"CWE-338","owasp":"A02:2021","confidence":"medium","pattern":"\\b(?:token|secret|nonce|password)\\w*\\s*=\\s*(?:scala\\.util\\.)?Random\\.(?:alphanumeric|nextInt|nextLong|nextBytes)\\b","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"crypto","recommendation":"Используйте java.security.SecureRandom для security-sensitive значений.","references":["https://cwe.mitre.org/data/definitions/338.html"]}},{"ruleId":"SCALA031","contentHash":"6cf5332987222ed9a916a59e81777e5cf9a58c781cbacc05d9e30962c04711e9","definition":{"id":"SCALA031","languages":["scala"],"title":"Play WS не проверяет hostname","description":"SSLLooseConfig явно отключает проверку имени TLS-сервера.","severity":"high","cwe":"CWE-297","owasp":"A02:2021","confidence":"high","pattern":"\\bdisableHostnameVerification\\s*(?:=|:)\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Включите проверку hostname и используйте сертификат с корректным SAN.","references":["https://cwe.mitre.org/data/definitions/297.html"]}},{"ruleId":"SCALA032","contentHash":"75984d57056a25fd8ea99a248a64a65a3d5a740af5205ee64ced1ac030af5278","definition":{"id":"SCALA032","languages":["scala"],"title":"Неэкранированный HTML в Play","description":"Html создаёт доверенный HTML-фрагмент из динамического значения.","severity":"high","cwe":"CWE-79","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:play\\.twirl\\.api\\.)?Html\\s*\\(\\s*(?:[A-Za-z_]|s\"[^\"\\n]*\\$)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"xss","recommendation":"Используйте штатное экранирование Twirl, очищайте необходимый HTML.","references":["https://cwe.mitre.org/data/definitions/79.html"]}},{"ruleId":"SCALA033","contentHash":"1d59272758c27ba5527c826f5236b4271770cc607393bc25b87a5ea4399e4be5","definition":{"id":"SCALA033","languages":["scala"],"title":"Play WS принимает любой сертификат","description":"WS-конфигурация явно принимает любой сертификат.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"high","pattern":"\\bacceptAnyCertificate\\s*(?:=|:)\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Отключите acceptAnyCertificate и настройте доверенное хранилище CA.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"SH030","contentHash":"a3f64c5fc70906e41814eec753c833cc5c013b20840c53501af9e46a0fb41372","definition":{"id":"SH030","languages":["shell"],"title":"SSH без проверки host key","description":"SSH отключает проверку ключа сервера.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"high","pattern":"\\b(?:ssh|scp|sftp)\\b[^\\n]*\\bStrictHostKeyChecking\\s*=\\s*no\\b","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Используйте StrictHostKeyChecking=yes и заранее проверенный known_hosts.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"SH031","contentHash":"cd853451525b6cb3ceebca5f21ab5a6713c21abdba6a7dbf1cbea8f71b48218e","definition":{"id":"SH031","languages":["shell"],"title":"Отключён known_hosts SSH","description":"SSH направляет known_hosts в /dev/null и не сохраняет доверенные ключи.","severity":"medium","cwe":"CWE-295","owasp":"A02:2021","confidence":"medium","pattern":"\\b(?:ssh|scp|sftp)\\b[^\\n]*\\bUserKnownHostsFile\\s*=\\s*\\/dev\\/null\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Храните проверенные ключи серверов в защищённом known_hosts.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"SH032","contentHash":"f539e746337f452ee83c6423d130e139c62712fb50ae7fadf76d8db892424443","definition":{"id":"SH032","languages":["shell"],"title":"Общедоступная umask","description":"umask 000/0000 позволяет создавать доступные всем файлы.","severity":"high","cwe":"CWE-732","owasp":"A05:2021","confidence":"high","pattern":"\\bumask\\s+0{3,4}(?=\\s|;|$)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Используйте umask 077 для секретных файлов или 027 для ограниченного группового доступа.","references":["https://cwe.mitre.org/data/definitions/732.html"]}},{"ruleId":"SH033","contentHash":"bbca288dd631dfab642a15a4ef2edb70d43b8c05cbbe0c2b177fcdeb0ca6bab4","definition":{"id":"SH033","languages":["shell"],"title":"Пароль в аргументах shell-команды","description":"Пароль sshpass/mysql передаётся литералом в аргументах процесса.","severity":"high","cwe":"CWE-214","owasp":"A07:2021","confidence":"medium","pattern":"\\bsshpass\\s+-p\\s+[\"''][^\"''\\n]+[\"'']|\\bmysql\\b[^\\n]*--password=[\"''][^\"''\\n]+[\"'']","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"secrets","recommendation":"Передавайте credentials через защищённый файл или secret store, исключите пароль из argv.","references":["https://cwe.mitre.org/data/definitions/214.html"]}},{"ruleId":"CFG030","contentHash":"17da8876084368db3ed97a9d987dde55382bb27b3f9e4c2236ca59c335486ce1","definition":{"id":"CFG030","languages":["config"],"title":"Kubernetes отключает non-root policy","description":"runAsNonRoot явно выключен.","severity":"medium","cwe":"CWE-250","owasp":"A05:2021","confidence":"medium","pattern":"\\brunAsNonRoot\\s*:\\s*false\\b","patternFlags":"i","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Установите runAsNonRoot: true и непривилегированный UID.","references":["https://cwe.mitre.org/data/definitions/250.html"]}},{"ruleId":"CFG031","contentHash":"5f42092d93f9b25cf678c927863c44e34cec9462e387543047ad503676ffb617","definition":{"id":"CFG031","languages":["config"],"title":"Kubernetes монтирует hostPath","description":"Pod получает доступ к каталог