ttps://cwe.mitre.org/data/definitions/89.html"]}},{"ruleId":"JS214","contentHash":"e9247bf7ef048b1820beb902d31a130155cbd0b98f2a41676427fc2bde9a9dc2","definition":{"id":"JS214","languages":["javascript","typescript"],"title":"MongoDB $function исполняет HTTP код","description":"MongoDB $function исполняет HTTP код. Недоверенные данные определяют выполняемый код, запрос или имя операции. Проверьте источник данных и условия применения.","severity":"critical","cwe":"CWE-95","owasp":"A03:2021","confidence":"medium","pattern":"\\$function\\s*:\\s*\\{[^}\\n]{0,200}\\bbody\\s*:\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Безопасная альтернатива: pipeline = { $project: { name: 1 } }; Используйте фиксированную операцию и параметры; выбирайте команды, классы и модули из разрешённого списка.","references":["https://cwe.mitre.org/data/definitions/95.html"]}},{"ruleId":"JS215","contentHash":"2173ab0638cf7c39b78fd56b5c62b210caf6c9039e5850e97bc9adc792c408a2","definition":{"id":"JS215","languages":["javascript","typescript"],"title":"Mongoose update напрямую из HTTP","description":"Mongoose update напрямую из HTTP. Недоверенные данные определяют выполняемый код, запрос или имя операции. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-915","owasp":"A03:2021","confidence":"medium","pattern":"\\.findByIdAndUpdate\\s*\\([^,\\n]+,\\s*(?:req|request)\\.body\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Безопасная альтернатива: User.findByIdAndUpdate(id, { displayName: validatedName }); Используйте фиксированную операцию и параметры; выбирайте команды, классы и модули из разрешённого списка.","references":["https://cwe.mitre.org/data/definitions/915.html"]}},{"ruleId":"JS216","contentHash":"3afe668f2e3d22a51ea02b3b411e9abcc0a5ac342a35f1a7a2b2c5f2903532eb","definition":{"id":"JS216","languages":["javascript","typescript"],"title":"Express download по HTTP пути","description":"Express download по HTTP пути. Ввод требует проверки путей, размеров, индексов или формата до использования. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-22","owasp":"A01:2021","confidence":"medium","pattern":"\\b(?:res|response)\\.download\\s*\\(\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"validation","recommendation":"Безопасная альтернатива: res.download(allowedPath); Проверяйте границы, формат и размер ввода; пути ограничивайте фиксированным каталогом после нормализации.","references":["https://cwe.mitre.org/data/definitions/22.html"]}},{"ruleId":"JS217","contentHash":"594b78301a92726e677962c74d1b9cfad0ed2dd90f8ce677dd4ccb97a6d89731","definition":{"id":"JS217","languages":["javascript","typescript"],"title":"Express end возвращает HTTP HTML","description":"Express end возвращает HTTP HTML. Недоверенные данные могут попасть в исполняемый HTML, JavaScript или CSS. Проверьте источник данных и условия применения.","severity":"high","cwe":"CWE-79","owasp":"A03:2021","confidence":"medium","pattern":"\\b(?:res|response)\\.end\\s*\\(\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"xss","recommendation":"Безопасная альтернатива: res.json({ text: req.query.html }); Сохраните экранирование по контексту; необходимый HTML очищайте по списку разрешённых элементов.","references":["https://cwe.mitre.org/data/definitions/79.html"]}},{"ruleId":"JS218","contentHash":"2378e30b39406961bc14964229f3160f1aab5e4f0e8d041c4b586cfdc260e4fa","definition":{"id":"JS218","languages":["javascript","typescript"],"title":"VM компилирует HTTP код","description":"VM компилирует HTTP код. Недоверенные данные определяют выполняемый код, запрос или имя операции. Проверьте источник данных и условия применения.","severity":"critical","cwe":"CWE-95","owasp":"A03:2021","confidence":"medium","pattern":"\\bnew\\s+vm\\.Script\\s*\\(\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Безопасная альтернатива: runAllowedAction(action); Используйте фиксированную операцию и параметры; выбирайте команды, классы и модули из разрешённого списка.","references":["https://cwe.mitre.org/data/definitions/95.html"]}},{"ruleId":"JS219","contentHash":"5e6c946a5582e7982bae0ce787916ac449ebdc05a1cef03a9140fc51b8f51496","definition":{"id":"JS219","languages":["javascript","typescript"],"title":"Fastify отключает request logging","description":"Fastify отключает request logging. Настройка может раскрыть секреты в логах либо исключить важные события аудита. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-778","owasp":"A09:2021","confidence":"medium","pattern":"\\bdisableRequestLogging\\s*:\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"logging","recommendation":"Безопасная альтернатива: fastify({ logger: true, disableRequestLogging: false }); Маскируйте credentials и чувствительные данные; сохраняйте необходимые события аудита с ограничением доступа.","references":["https://cwe.mitre.org/data/definitions/778.html"]}},{"ruleId":"JS220","contentHash":"7dfb66066186894b00f25e845ea95ad13af05d624190ba2db3a3fc5f2f6f41fd","definition":{"id":"JS220","languages":["javascript","typescript"],"title":"require выбирает HTTP модуль","description":"require выбирает HTTP модуль. Недоверенные данные определяют выполняемый код, запрос или имя операции. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-829","owasp":"A03:2021","confidence":"medium","pattern":"\\brequire\\s*\\(\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Безопасная альтернатива: require(''./known-handler.cjs''); Используйте фиксированную операцию и параметры; выбирайте команды, классы и модули из разрешённого списка.","references":["https://cwe.mitre.org/data/definitions/829.html"]}},{"ruleId":"JS221","contentHash":"c9861ac6e9a1956569e43c670079abcd3b3f1a741171c76fd311a2a3e705d060","definition":{"id":"JS221","languages":["javascript","typescript"],"title":"Динамический import из HTTP","description":"Динамический import из HTTP. Недоверенные данные определяют выполняемый код, запрос или имя операции. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-829","owasp":"A03:2021","confidence":"medium","pattern":"\\bimport\\s*\\(\\s*(?:req|request)\\.","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"injection","recommendation":"Безопасная альтернатива: import(''./known-handler.js''); Используйте фиксированную операцию и параметры; выбирайте команды, классы и модули из разрешённого списка.","references":["https://cwe.mitre.org/data/definitions/829.html"]}},{"ruleId":"JS222","contentHash":"81a542e158079f0611925c85bb935a5ab4ca198012e7226c0264a33d7477f1d6","definition":{"id":"JS222","languages":["javascript","typescript"],"title":"DOMPurify отключает XML safeguards","description":"DOMPurify отключает XML safeguards. Недоверенные данные могут попасть в исполняемый HTML, JavaScript или CSS. Проверьте источник данных и условия применения.","severity":"high","cwe":"CWE-79","owasp":"A03:2021","confidence":"medium","pattern":"\\bSAFE_FOR_XML\\s*:\\s*false\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"xss","recommendation":"Безопасная альтернатива: DOMPurify.sanitize(html, { SAFE_FOR_XML: true }); Сохраните экранирование по контексту; необходимый HTML очищайте по списку разрешённых элементов.","references":["https://cwe.mitre.org/data/definitions/79.html"]}},{"ruleId":"JS223","contentHash":"0f6e3e9a9ef9720cc2586aec5fdf8a6b55cee7b6cbb39b692401e2f5c059f116","definition":{"id":"JS223","languages":["javascript","typescript"],"title":"Helmet полностью отключает CSP","description":"Helmet полностью отключает CSP. Проверьте необходимость настройки в production и границу доверия. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-693","owasp":"A05:2021","confidence":"medium","pattern":"\\bcontentSecurityPolicy\\s*:\\s*false\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Безопасная альтернатива: helmet({ contentSecurityPolicy: { useDefaults: true } }); Отключите опасную возможность в production либо ограничьте её изолированным окружением и проверенным содержимым.","references":["https://cwe.mitre.org/data/definitions/693.html"]}},{"ruleId":"JS224","contentHash":"b061572250aa40634e541f663880d9cf06502846506c6c174361ebbafd4894d9","definition":{"id":"JS224","languages":["javascript","typescript"],"title":"Cookie session без подписи","description":"Cookie session без подписи. Настройка требует проверки целостности сессий и защиты credentials. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-565","owasp":"A07:2021","confidence":"medium","pattern":"\\bsigned\\s*:\\s*false\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"authentication","recommendation":"Безопасная альтернатива: cookieSession({ signed: true, keys: signingKeys }); Проверяйте подпись и обязательные claims; защищайте сессии Secure, HttpOnly, SameSite и CSRF-проверкой.","references":["https://cwe.mitre.org/data/definitions/565.html"]}},{"ruleId":"JS225","contentHash":"8f96e44a13a879c5e0b1de76d16018d0ad107b5a2a1fe2557060639a6b1aac3f","definition":{"id":"JS225","languages":["javascript","typescript"],"title":"Axios снимает лимит ответа","description":"Axios снимает лимит ответа. Ввод требует проверки путей, размеров, индексов или формата до использования. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-400","owasp":"A01:2021","confidence":"medium","pattern":"\\bmaxC