щайте сессии Secure, HttpOnly, SameSite и CSRF-проверкой.","references":["https://cwe.mitre.org/data/definitions/614.html"]}},{"ruleId":"RS219","contentHash":"0620c2e0a508e756c0e72b25d56bddefa3b9ddfd90b6f0e1e1e33e345f8e7eff","definition":{"id":"RS219","languages":["rust"],"title":"Rust отключает HttpOnly cookie","description":"Rust отключает HttpOnly cookie. Настройка требует проверки целостности сессий и защиты credentials. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-1004","owasp":"A07:2021","confidence":"medium","pattern":"\\.http_only\\s*\\(\\s*false\\s*\\)","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"authentication","recommendation":"Безопасная альтернатива: Cookie::build((\"session\", token)).http_only(true); Проверяйте подпись и обязательные claims; защищайте сессии Secure, HttpOnly, SameSite и CSRF-проверкой.","references":["https://cwe.mitre.org/data/definitions/1004.html"]}},{"ruleId":"SWIFT200","contentHash":"38924ecca83f39eb1b7dfcfd490d3ca5cfc244e59e22740e515abe84a6ae17b4","definition":{"id":"SWIFT200","languages":["swift"],"title":"Swift Keychain доступен после первой разблокировки","description":"Swift Keychain доступен после первой разблокировки. Настройка требует проверки целостности сессий и защиты credentials. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-922","owasp":"A07:2021","confidence":"medium","pattern":"\\bkSecAttrAccessibleAfterFirstUnlock\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"authentication","recommendation":"Безопасная альтернатива: query[kSecAttrAccessible] = kSecAttrAccessibleWhenUnlockedThisDeviceOnly Проверяйте подпись и обязательные claims; защищайте сессии Secure, HttpOnly, SameSite и CSRF-проверкой.","references":["https://cwe.mitre.org/data/definitions/922.html"]}},{"ruleId":"SWIFT201","contentHash":"27b97e32d5a0569d750b2881ae06f423ed1183bf8f95363c36437be082ae1411","definition":{"id":"SWIFT201","languages":["swift"],"title":"Swift Keychain синхронизирует секрет","description":"Swift Keychain синхронизирует секрет. Настройка требует проверки целостности сессий и защиты credentials. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-922","owasp":"A07:2021","confidence":"medium","pattern":"\\bkSecAttrSynchronizable\\s*:\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"authentication","recommendation":"Безопасная альтернатива: let query = [kSecAttrSynchronizable: false] Проверяйте подпись и обязательные claims; защищайте сессии Secure, HttpOnly, SameSite и CSRF-проверкой.","references":["https://cwe.mitre.org/data/definitions/922.html"]}},{"ruleId":"SWIFT202","contentHash":"85eb24538262c2e0201c8d4bef4582e36f05eb7bcba70006bbd0dd4d159df9be","definition":{"id":"SWIFT202","languages":["swift"],"title":"Swift WebView universal file access","description":"Swift WebView universal file access. Проверьте необходимость настройки в production и границу доверия. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-346","owasp":"A05:2021","confidence":"medium","pattern":"\\.setValue\\s*\\(\\s*true\\s*,\\s*forKey:\\s*\"allowUniversalAccessFromFileURLs\"","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Безопасная альтернатива: prefs.setValue(false, forKey: \"allowUniversalAccessFromFileURLs\") Отключите опасную возможность в production либо ограничьте её изолированным окружением и проверенным содержимым.","references":["https://cwe.mitre.org/data/definitions/346.html"]}},{"ruleId":"SWIFT203","contentHash":"32060335f6d9a39cd49d40bc1575f18e3acf710bbd13cb355f361f3ab06a1f0d","definition":{"id":"SWIFT203","languages":["swift"],"title":"Swift WebView JavaScript popups","description":"Swift WebView JavaScript popups. Проверьте необходимость настройки в production и границу доверия. Проверьте источник данных и условия применения.","severity":"medium","cwe":"CWE-1021","owasp":"A05:2021","confidence":"medium","pattern":"\\.javaScriptCanOpenWindowsAutomatically\\s*=\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"configuration","recommendation":"Безопасная альтернатива: prefs.javaScriptCanOpenWindowsAutomatically = false Отключите опасную возможность в production либо ограничьте её изолированным окружением и проверенным содержимым.","references":["https://cwe.mitre.org/data/definitions/1021.html"]}},{"ruleId":"SWIFT204","contentHash":"05bcd370574eee44a402faa0cf07be283d370eb87b110388af9e859f8af1d0a2","definition":{"id":"SWIFT204","languages":["swift"],"title":"Swift Alamofire отключает trust evaluator","description":"Swift Alamofire отключает trust evaluator. Настройка ослабляет аутентификацию сервера или защиту сетевого соединения. Проверьте источник данных и условия применения.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"medium","pattern":"\\bDisabledTrustEvaluator\\s*\\(","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Безопасная альтернатива: DefaultTrustEvaluator() Используйте TLS 1.2 или новее, проверяйте сертификат и имя сервера с доверенным CA.","references":["https://cwe.mitre.org/data/definitions/295.html"]}},{"ruleId":"SWIFT205","contentHash":"1a82d54a335d8d7777724d8303cc8bb001d533b672328705cf9b7e9c45081f8a","definition":{"id":"SWIFT205","languages":["swift"],"title":"Swift Alamofire принимает self-signed","description":"Swift Alamofire принимает self-signed. Настройка ослабляет аутентификацию сервера или защиту сетевого соединения. Проверьте источник данных и условия применения.","severity":"high","cwe":"CWE-295","owasp":"A02:2021","confidence":"medium","pattern":"\\bacceptSelfSignedCertificates\\s*:\\s*true\\b","patternFlags":"","exclude":null,"excludeFlags":null,"scope":"line","category":"transport","recommendation":"Безопасная альт